static uint8_t channel(unsigned long value,unsigned long mask){if(!mask)return 0;while(!(mask&1)){value>>=1;mask>>=1;}return uint8_t(((value&mask)*255+mask/2)/mask);}
static bool physical(Display*d,Window window,unsigned extent,Frame&frame){XSync(d,False);XImage*image=XGetImage(d,window,0,0,extent,extent,AllPlanes,ZPixmap);if(!image)return false;frame.rgba.resize(size_t(extent)*extent*4);for(unsigned y=0;y<extent;++y)for(unsigned x=0;x<extent;++x){auto value=XGetPixel(image,x,y);size_t i=(size_t(y)*extent+x)*4;frame.rgba[i]=channel(value,image->red_mask);frame.rgba[i+1]=channel(value,image->green_mask);frame.rgba[i+2]=channel(value,image->blue_mask);frame.rgba[i+3]=255;}XDestroyImage(image);return true;}
static bool match(const Frame&a,const Frame&b){if(a.rgba.size()!=b.rgba.size()||a.rgba.empty())return false;for(size_t i=0;i<a.rgba.size();i+=4){for(unsigned c=0;c<3;++c)if(std::abs(int(a.rgba[i+c])-int(b.rgba[i+c]))>3)return false;if(a.rgba[i+3]!=255||b.rgba[i+3]!=255)return false;}return true;}
static bool presented(Display*d,Window window,unsigned extent,const Frame&read,Frame&shown,const char*phase){auto begin=std::chrono::steady_clock::now(),deadline=begin+std::chrono::seconds(5);unsigned attempts=0;bool good=false;do{++attempts;if(physical(d,window,extent,shown)&&match(read,shown)&&std::chrono::steady_clock::now()<=deadline){good=true;break;}}while(std::chrono::steady_clock::now()<deadline);std::cout<<"cube_window_present phase="<<phase<<" extent="<<extent<<" attempts="<<attempts<<" elapsed_ms="<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-begin).count()<<" matched="<<good<<'\n';return check(good,"whole physical current cube consumer matches immediate readback within existing5s, no reapply");}

static bool windowCoverage(const Frame&frame,const Source&source,unsigned extent,unsigned samples){FaceOracle oracle(source,32);std::array<RGBA,54>colors;for(unsigned cell=0;cell<54;++cell)colors[cell]=oracle.sample(panelDirection(cell),0,0);unsigned bad=0,empty=0,full=0,partial=0,odd=0;for(unsigned y=0;y<extent;++y)for(unsigned x=0;x<extent;++x){const size_t p=(size_t(y)*extent+x)*4;int selected=-1;double best=std::numeric_limits<double>::infinity();double zeroError=0;bool zeroValid=true;for(unsigned c=0;c<3;++c){zeroValid &=frame.rgba[p+c]<=3;zeroError+=double(frame.rgba[p+c])*frame.rgba[p+c];}if(zeroValid){selected=0;best=zeroError;}for(unsigned cell=0;cell<54;++cell){const double cx=-3.2+.8*(cell%9),cy=2.-.8*(cell/9),left=extent*.5+(cx-.32)*extent/8,right=extent*.5+(cx+.32)*extent/8,top=extent*.5-(cy+.32)*extent/8,bottom=extent*.5-(cy-.32)*extent/8;if(x+.5<left-.75||x+.5>right+.75||y+.5<top-.75||y+.5>bottom+.75)continue;for(unsigned k=1;k<=samples;++k){double error=0;bool valid=true;for(unsigned c=0;c<3;++c){const double expected=colors[cell][c]*k/samples,delta=frame.rgba[p+c]-expected;error+=delta*delta;valid &=std::abs(int(frame.rgba[p+c])-int(std::lround(expected)))<=3;}if(valid&&error<best){best=error;selected=int(k);}}}if((selected<0||frame.rgba[p+3]!=255)&&bad<4)std::cout<<"cube_window_coverage_first xy="<<x<<','<<y<<" rgb="<<unsigned(frame.rgba[p])<<','<<unsigned(frame.rgba[p+1])<<','<<unsigned(frame.rgba[p+2])<<'\n';bad+=selected<0||frame.rgba[p+3]!=255;empty+=selected==0;full+=selected==int(samples);partial+=selected>0&&selected<int(samples);odd+=selected>0&&selected<int(samples)&&(selected&1);}std::cout<<"cube_window_coverage extent="<<extent<<" samples="<<samples<<" bad="<<bad<<" empty="<<empty<<" full="<<full<<" partial="<<partial<<" odd="<<odd<<'\n';return check(bad==0&&empty>100&&full>100&&(samples==1||partial>0)&&(samples!=4||odd>0),"whole current window RGB equals closest admissible k/N, effective2/4 coverage and opaque alpha");}
static bool oracle(const Frame&f,const Scene&scene,const Source&source,unsigned extent,unsigned samples){if(!check(f.rgba.size()==size_t(extent)*extent*4,"window whole readback current extent"))return false;FaceOracle reference(source,32);unsigned bad=0;int maximum=0;for(unsigned cell=0;cell<54;++cell){double cx=-3.2+.8*(cell%9),cy=2.-.8*(cell/9);int px=int(std::lround(extent*.5+cx*extent/8-.5)),py=int(std::lround(extent*.5-cy*extent/8-.5));auto e=reference.sample(panelDirection(cell),0,0);for(int dy=-1;dy<=1;++dy)for(int dx=-1;dx<=1;++dx){size_t i=(size_t(py+dy)*extent+unsigned(px+dx))*4;for(unsigned c=0;c<3;++c){int delta=std::abs(int(f.rgba[i+c])-int(std::lround(e[c])));maximum=std::max(maximum,delta);bad+=delta>3;}bad+=f.rgba[i+3]!=255;}}std::cout<<"cube_window_oracle bad="<<bad<<" max="<<maximum<<'\n';return check(bad==0,"window six asymmetric faces, mathematical camera ray/texture oracle")&&windowCoverage(f,source,extent,samples);}
int main(int argc,char**argv){configureSamplingTest(argc,argv);unsigned samples=1;CoinRenderSceneTextureMode route=COIN_RENDER_SCENE_TEXTURE_STAGED;for(int i=1;i<argc;++i){std::string arg=argv[i];if(arg=="--samples"&&i+1<argc){if(!unsignedOption(argv[++i],samples))return 2;}else if(arg=="--direct")route=COIN_RENDER_SCENE_TEXTURE_DIRECT;else if(arg=="--staged")route=COIN_RENDER_SCENE_TEXTURE_STAGED;else if(arg=="--portable-sampling"){}else return 2;}if(samples!=1&&samples!=2&&samples!=4)return 2;if(!XInitThreads())return 1;SoDB::init();CoinRenderAction::initClass();CoinRenderCapabilities caps{};if(coin_render_query_capabilities(COIN_RENDER_EXPERIMENTAL_XLIB_WINDOW,&caps,sizeof(caps)))return 1;if(!caps.gpu_available)return 77;Display*d=XOpenDisplay(nullptr);if(!d)return 77;unsigned extent=192;Window window=XCreateSimpleWindow(d,DefaultRootWindow(d),16,16,extent,extent,0,0,0);XSetWindowAttributes attributes{};attributes.override_redirect=True;XChangeWindowAttributes(d,window,CWOverrideRedirect,&attributes);XMapRaised(d,window);XSync(d,False);CoinRenderNativeSurfaceDescriptor native{};native.abiVersion=COIN_RENDER_NATIVE_SURFACE_ABI_VERSION;native.structSize=sizeof(native);native.type=COIN_RENDER_SURFACE_XLIB;native.native.xlib.display=d;native.native.xlib.window=window;auto options=samplingTestOptions();options.renderer=static_cast<CoinRenderRenderer>(caps.renderer);options.sampleCount=samples;options.sceneTexture=route;std::unique_ptr<CoinRenderTarget>target(CoinRenderTarget::createWindow(native,SbVec2i32(extent,extent),options));if(!check(bool(target)&&target->getStatus()==CoinRenderTarget::TARGET_READY,"cube root X11 target"))return 1;CoinRenderAction action(SbViewportRegion(extent,extent));action.setRenderTarget(target.get());action.setTransparencyType(CoinRenderAction::NONE);action.setBackgroundColor(SbColor4f(0,0,0,1));Scene scene;Source source;scene.cube->scene=source.root;scene.enabled->whichChild=SO_SWITCH_ALL;auto slope=scene.vertices[0]->point[3];slope[1]-=.13f;scene.vertices[0]->point.set1Value(3,slope);Frame first,firstShown,read,shown;auto draw=[&](Frame&f,Frame&physicalFrame,const char*phase){auto serial=target->getLastSubmissionSerial();bool requested=target->requestWindowReadbackRGBA();action.apply(scene.root);target->readbackRGBA(f.rgba);f.serial=target->getLastSubmissionSerial();std::cout<<"cube_window phase="<<phase<<" samples="<<samples<<" serial="<<f.serial<<" status="<<action.getLastStatus()<<" error="<<action.getLastError().getString()<<'\n';if(!check(requested&&action.getLastStatus()==CoinRenderAction::SUCCESS&&f.serial>serial&&target->getOptions().sampleCount==samples,"one apply publishes current explicit window cube readback"))return false;if(!oracle(f,scene,source,extent,samples))return false;return presented(d,window,extent,f,physicalFrame,phase)&&oracle(physicalFrame,scene,source,extent,samples);};bool ok=draw(first,firstShown,"cold cube window");if(!ok)return 1;ok &=check(source.callbacks==6,"window root captures six logical producer faces only");auto retained=[&](const char*phase){Frame a,b;target->readbackRGBA(a.rgba);bool seen=physical(d,window,extent,b);return check(target->getLastSubmissionSerial()==first.serial&&a.rgba==first.rgba&&seen&&b.rgba==firstShown.rgba,std::string("peer preserves original window publication: ")+phase);};{Source peerSource;Scene peerScene;peerScene.cube->scene=peerSource.root;peerScene.enabled->whichChild=SO_SWITCH_ALL;Harness peer(samples,false,route);Frame a,b,c;ok &=peer.render(peerScene.root,a,"live cube peer")&&gradientCenters(a,FaceOracle(peerSource,32),"live cube peer");ok &=retained("peer rendered");peerSource.paint(1);ok &=peer.render(peerScene.root,b,"cube peer changed")&&gradientCenters(b,FaceOracle(peerSource,32),"cube peer changed");ok &=retained("peer changed");peerScene.cube->size.setValue(0,16);ok &=peer.reject(peerScene.root,b,"peer invalid cube extent");ok &=retained("peer refused");peerScene.cube->size.setValue(32,32);ok &=peer.render(peerScene.root,c,"peer invalid recovery")&&exact(b,c);ok &=retained("peer recovered");}
 ok &=retained("peer destroyed");source.paint(1);ok &=draw(read,shown,"cube window producer mutation");source.paint(0);ok &=draw(read,shown,"cube window A/B/A")&&check(read.rgba==first.rgba&&shown.rgba==firstShown.rgba,"window exact scene A/B/A");for(unsigned size:{97u,240u,192u}){extent=size;XResizeWindow(d,window,size,size);XSync(d,False);ok &=check(target->resize(SbVec2i32(size,size)),"cube window resize");action.setViewportRegion(SbViewportRegion(size,size));ok &=draw(read,shown,"cube window resized physical/readback");}auto stable=read,stableShown=shown;auto serial=target->getLastSubmissionSerial();scene.cube->size.setValue(16,0);target->requestWindowReadbackRGBA();action.apply(scene.root);Frame after;ok &=check(action.getLastStatus()!=CoinRenderAction::SUCCESS&&target->getLastSubmissionSerial()==serial&&physical(d,window,extent,after)&&after.rgba==stableShown.rgba,"invalid cube preflight leaves window physical pixels/serial intact");scene.cube->size.setValue(32,32);ok &=draw(read,shown,"cube window invalid recovery")&&check(read.rgba==stable.rgba&&shown.rgba==stableShown.rgba,"window recovery exact");action.setRenderTarget(nullptr);target.reset();XDestroyWindow(d,window);XCloseDisplay(d);return ok?0:1;}
